{"command":"python3 - <<'PY'
import subprocess, pathlib, os, shutil
base="/tmp/hash1"
if os.path.exists(base): shutil.rmtree(base)
os.makedirs(base)
pathlib.Path(base+"/go.mod").write_text("module example.com/hash1\n\ngo 1.21\n")
pathlib.Path(base+"/a.go").write_text('''package p
import ("hash"; "hash/crc32"; "crypto/sha256"; "io"; "bytes")
func use() {
    var h hash.Hash = sha256.New()
    h.Write([]byte("x"))
    var h32 hash.Hash32 = crc32.NewIEEE()
    h32.Write([]byte("x"))
    var w io.Writer = &bytes.Buffer{}
    w.Write([]byte("x"))
    var b bytes.Buffer
    b.Write([]byte("x"))
    // also direct sha256 digest? sha256.New returns hash.Hash
    hh := sha256.New()
    hh.Write([]byte("x"))
}
''')
def run(args):
    p=subprocess.run(["/workspace/executable"]+args,cwd=base,capture_output=True,text=True)
    print(args, p.returncode)
    print(p.stdout)
    print("err",repr(p.stderr))
run(["-verbose","./..."])
run(["-verbose","-excludeonly","./..."])
for ex in ["(hash.Hash).Write\n","(io.Writer).Write\n","(hash.Hash32).Write\n","(hash.Hash).Write\n(hash.Hash32).Write\n(io.Writer).Write\n"]:
    pathlib.Path("/tmp/ex.txt").write_text(ex)
    print("EXCLUDE file:", repr(ex))
    run(["-verbose","-excludeonly","-exclude","/tmp/ex.txt","./..."])
PY
"}

