{"command":"python3 - <<'PY'
import subprocess, pathlib, os, shutil
base="/tmp/embed1"
if os.path.exists(base): shutil.rmtree(base)
os.makedirs(base+"/sub")
pathlib.Path(base+"/go.mod").write_text("module example.com/embed1\n\ngo 1.21\n")
pathlib.Path(base+"/sub/sub.go").write_text('''package sub
import "io"
type A interface { Foo() error }
type B interface { A; Bar() error }
type C interface { B }
type S struct{}
func (s S) Foo() error { return nil }
func (s *S) PFoo() error { return nil }
type T struct { S }
type PT struct { *S }
type Impl struct{}
func (Impl) Foo() error { return nil }
func (Impl) Write(p []byte) (int,error){ return 0,nil }
var _ io.Writer = Impl{}
var _ A = Impl{}
''')
pathlib.Path(base+"/a.go").write_text('''package p
import ("example.com/embed1/sub"; "io")
func use(a sub.A, b sub.B, c sub.C, s sub.S, ps *sub.S, t sub.T, pt sub.PT, impl sub.Impl, w io.Writer) {
    a.Foo() // 4
    b.Foo()
    c.Foo()
    b.Bar()
    c.Bar()
    s.Foo()
    s.PFoo()
    ps.Foo()
    ps.PFoo()
    t.Foo()
    t.PFoo()
    pt.Foo()
    pt.PFoo()
    impl.Foo()
    impl.Write(nil)
    w.Write(nil)
}
''')
def run(args):
    p=subprocess.run(["/workspace/executable"]+args,cwd=base,capture_output=True,text=True)
    print(args, p.returncode)
    print(p.stdout)
    if p.stderr: print("err",repr(p.stderr))
run(["-verbose","-excludeonly","./..."])
tests=[
 "(example.com/embed1/sub.A).Foo\n",
 "(example.com/embed1/sub.B).Foo\n",
 "(example.com/embed1/sub.C).Foo\n",
 "(example.com/embed1/sub.B).Bar\n",
 "(example.com/embed1/sub.A).Bar\n", # nonsense
 "(example.com/embed1/sub.S).Foo\n",
 "(*example.com/embed1/sub.S).PFoo\n",
 "(example.com/embed1/sub.T).Foo\n",
 "(example.com/embed1/sub.PT).Foo\n",
 "(example.com/embed1/sub.Impl).Foo\n",
 "(io.Writer).Write\n",
 "(example.com/embed1/sub.Impl).Write\n",
]
for ex in tests:
    pathlib.Path("/tmp/ex.txt").write_text(ex)
    print("EXCLUDE",ex.strip())
    run(["-verbose","-excludeonly","-exclude","/tmp/ex.txt","."])
PY
"}

