{"command":"cat > /tmp/loadtest/main.go <<'GO'
package main

import (
 "fmt"
 "os"
 "go/ast"
 "go/types"
 "golang.org/x/tools/go/packages"
)
func qual(p *types.Package) string { if p==nil {return ""}; return p.Path() }
func main(){
 cfg:=&packages.Config{Mode: packages.NeedName|packages.NeedTypes|packages.NeedSyntax|packages.NeedTypesInfo, Tests:true, Dir: os.Args[1]}
 pkgs, err:=packages.Load(cfg, os.Args[2:]...)
 if err!=nil {fmt.Println("loaderr",err); }
 for _,pkg:=range pkgs{
   fmt.Println("pkg",pkg.PkgPath, pkg.Errors)
   for _,file:=range pkg.Syntax{
     ast.Inspect(file, func(n ast.Node) bool{
       sel, ok:=n.(*ast.SelectorExpr)
       if !ok {return true}
       info:=pkg.TypesInfo
       s:=info.Selections[sel]
       use:=info.Uses[sel.Sel]
       xType:=info.TypeOf(sel.X)
       fmt.Printf("sel %s.%s Xtype=%s Use=%v UseType=%T", fmt.Sprint(sel.X), sel.Sel.Name, types.TypeString(xType, qual), use, use)
       if fn,ok:=use.(*types.Func); ok {
         sig:=fn.Type().(*types.Signature)
         if sig.Recv()!=nil {
            fmt.Printf(" recvType=%s", types.TypeString(sig.Recv().Type(), qual))
         } else { fmt.Printf(" recv=nil pkg=%v", fn.Pkg()) }
       }
       if s!=nil {
         fmt.Printf(" | Selection kind=%v recv=%s obj=%v index=%v indirect=%v seltype=%s", s.Kind(), types.TypeString(s.Recv(),qual), s.Obj(), s.Index(), s.Indirect(), types.TypeString(s.Type(),qual))
       } else {
         fmt.Printf(" | Selection=nil")
       }
       fmt.Println()
       return true
     })
   }
 }
}
GO
