package main
import ("fmt";"os";"go/ast";"go/types";"golang.org/x/tools/go/packages")
func qual(p *types.Package) string { if p==nil {return ""}; return p.Path() }
func main(){
 cfg:=&packages.Config{Mode: packages.NeedName|packages.NeedTypes|packages.NeedSyntax|packages.NeedTypesInfo, Tests:true, Dir: os.Args[1]}
 pkgs,_:=packages.Load(cfg, os.Args[2:]...)
 for _,pkg:=range pkgs{
  for _,file:=range pkg.Syntax{
   ast.Inspect(file, func(n ast.Node) bool{
    sel,ok:=n.(*ast.SelectorExpr); if !ok {return true}
    s:=pkg.TypesInfo.Selections[sel]; if s==nil {return true}
    fmt.Printf("%s Recv=%s (%T) index=%v objFull=", sel.Sel.Name, types.TypeString(s.Recv(),qual), s.Recv(), s.Index())
    if fn,ok:=s.Obj().(*types.Func);ok{fmt.Printf("%q",fn.FullName())}
    fmt.Println()
    // walk fields manually rough
    curr:=s.Recv()
    for _,idx:=range s.Index()[:max(0,len(s.Index())-1)] {
       for { if p,ok:=curr.(*types.Pointer);ok{curr=p.Elem(); continue}; break }
       fmt.Printf("  step idx %d curr %s (%T underlying %T)",idx,types.TypeString(curr,qual),curr,curr.Underlying())
       if st,ok:=curr.Underlying().(*types.Struct);ok {
          f:=st.Field(idx); fmt.Printf(" -> field %s type %s (%T)\n",f.Name(),types.TypeString(f.Type(),qual),f.Type()); curr=f.Type()
       } else {fmt.Println(" -> nonstruct");break}
    }
    return true
   })
  }
 }
}
func max(a,b int)int{if a>b {return a};return b}
