{"command":"cat > main.go <<'GO'
package main

import (
	"bufio"
	"flag"
	"fmt"
	"go/ast"
	"go/token"
	"go/types"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"

	"golang.org/x/tools/go/packages"
)

// uncheckedError is one reported use of a value that the checker requires
// to be inspected.
type uncheckedError struct {
	pos      token.Position
	selector string
	line     string
}

// ignoreFlag is the deprecated -ignore flag.  It maps a package path (or
// the empty string for every package) to a regular expression matched
// against the final name of the function, method, field or type being
// called.
type ignoreFlag map[string]*regexp.Regexp

func (f ignoreFlag) String() string { return "" }

func (f ignoreFlag) Set(value string) error {
	if value == "" {
		return nil
	}
	for _, part := range strings.Split(value, ",") {
		pkg, pattern, found := strings.Cut(part, ":")
		if !found {
			pkg = ""
			pattern = part
		}
		re, err := regexp.Compile(pattern)
		if err != nil {
			return err
		}
		f[pkg] = re
	}
	return nil
}

// tagsFlag collects build tags.  A single flag may contain several tags
// separated by commas or spaces, and the flag may be repeated.
type tagsFlag []string

func (f *tagsFlag) String() string {
	if f == nil {
		return ""
	}
	return strings.Join(*f, " ")
}

func (f *tagsFlag) Set(value string) error {
	tags := strings.FieldsFunc(value, func(r rune) bool {
		return r == ',' || r == ' '
	})
	*f = append(*f, tags...)
	return nil
}

var defaultExcludes = []string{
	"(*bytes.Buffer).Write",
	"(*bytes.Buffer).WriteByte",
	"(*bytes.Buffer).WriteRune",
	"(*bytes.Buffer).WriteString",
	"(*strings.Builder).Write",
	"(*strings.Builder).WriteByte",
	"(*strings.Builder).WriteRune",
	"(*strings.Builder).WriteString",
	"(hash.Hash).Write",
	"(*hash/maphash.Hash).Write",
	"(*hash/maphash.Hash).WriteByte",
	"(*hash/maphash.Hash).WriteString",
	"crypto/rand.Read",
	"math/rand.Read",
	"(*math/rand.Rand).Read",
	"(*io.PipeReader).CloseWithError",
	"(*io.PipeWriter).CloseWithError",
	"fmt.Print",
	"fmt.Printf",
	"fmt.Println",
	"fmt.Fprint(*bytes.Buffer)",
	"fmt.Fprintf(*bytes.Buffer)",
	"fmt.Fprintln(*bytes.Buffer)",
	"fmt.Fprint(*strings.Builder)",
	"fmt.Fprintf(*strings.Builder)",
	"fmt.Fprintln(*strings.Builder)",
	"fmt.Fprint(os.Stderr)",
	"fmt.Fprintf(os.Stderr)",
	"fmt.Fprintln(os.Stderr)",
}

func readExcludes(filename string) (map[string]bool, error) {
	file, err := os.Open(filename)
	if err != nil {
		return nil, err
	}
	defer func() { _ = file.Close() }()

	excludes := make(map[string]bool)
	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		line := scanner.Text()
		if line == "" || strings.HasPrefix(line, "//") {
			continue
		}
		excludes[line] = true
	}
	if err := scanner.Err(); err != nil {
		return nil, err
	}
	return excludes, nil
}

type checkerConfig struct {
	blank           bool
	asserts         bool
	ignoreGenerated bool
	ignore          ignoreFlag
	excludes        map[string]bool
	verbose         bool
}

func main() {
	var (
		abspath         bool
		asserts         bool
		blank           bool
		excludeFile     string
		excludeOnly     bool
		ignoreGenerated bool
		ignorePkg       string
		ignoreTests     bool
		mod             string
		verbose         bool
	)

	ignore := make(ignoreFlag)
	var tags tagsFlag

	flag.BoolVar(&abspath, "abspath", false, "print absolute paths to files")
	flag.BoolVar(&asserts, "asserts", false, "if true, check for ignored type assertion results")
	flag.BoolVar(&blank, "blank", false, "if true, check for errors assigned to blank identifier")
	flag.StringVar(&excludeFile, "exclude", "", "Path to a file containing a list of functions to exclude from checking")
	flag.BoolVar(&excludeOnly, "excludeonly", false, "Use only excludes from -exclude file")
	flag.Var(ignore, "ignore", "[deprecated] comma-separated list of pairs of the form pkg:regex\n            the regex is used to ignore names within pkg.")
	flag.BoolVar(&ignoreGenerated, "ignoregenerated", false, "if true, checking of files with generated code is disabled")
	flag.StringVar(&ignorePkg, "ignorepkg", "", "comma-separated list of package paths to ignore")
	flag.BoolVar(&ignoreTests, "ignoretests", false, "if true, checking of _test.go files is disabled")
	flag.StringVar(&mod, "mod", "", "module download mode to use: readonly or vendor. See 'go help modules' for more.")
	flag.Var(&tags, "tags", "comma or space-separated list of build tags to include")
	flag.BoolVar(&verbose, "verbose", false, "produce more verbose logging")
	flag.Parse()

	excludes := make(map[string]bool)
	if excludeFile != "" {
		fromFile, err := readExcludes(excludeFile)
		if err != nil {
			_, _ = fmt.Fprintf(os.Stderr, "Could not read exclude file: %v\n", err)
			os.Exit(2)
		}
		for name := range fromFile {
			excludes[name] = true
		}
	}
	if !excludeOnly {
		for _, name := range defaultExcludes {
			excludes[name] = true
		}
	}

	if ignorePkg != "" {
		all := regexp.MustCompile(".*")
		for _, pkg := range strings.Split(ignorePkg, ",") {
			if pkg == "" {
				continue
			}
			ignore[pkg] = all
		}
	}

	buildFlags := []string{fmt.Sprintf("-tags=%s", strings.Join(tags, ","))}
	if mod != "" {
		buildFlags = append(buildFlags, fmt.Sprintf("-mod=%s", mod))
	}

	cfg := checkerConfig{
		blank:           blank,
		asserts:         asserts,
		ignoreGenerated: ignoreGenerated,
		ignore:          ignore,
		excludes:        excludes,
		verbose:         verbose,
	}

	unchecked, err := checkPackages(cfg, buildFlags, ignoreTests, flag.Args())
	if err != nil {
		_, _ = fmt.Fprintf(os.Stderr, "error: failed to check packages: %v\n", err)
		os.Exit(2)
	}

	wd, _ := os.Getwd()
	for _, item := range unchecked {
		pos := displayPosition(item.pos, wd, abspath)
		if verbose && item.selector != "" {
			_, _ = fmt.Fprintf(os.Stdout, "%s:\t%s\t%s\n", pos, item.selector, item.line)
		} else {
			_, _ = fmt.Fprintf(os.Stdout, "%s:\t%s\n", pos, item.line)
		}
	}
	if len(unchecked) != 0 {
		os.Exit(1)
	}
}

func displayPosition(pos token.Position, wd string, abspath bool) string {
	display := pos
	if display.Filename != "" {
		if abspath {
			if abs, err := filepath.Abs(display.Filename); err == nil {
				display.Filename = abs
			}
		} else if wd != "" {
			if rel, err := filepath.Rel(wd, display.Filename); err == nil {
				display.Filename = rel
			}
		}
	}
	return display.String()
}

func checkPackages(cfg checkerConfig, buildFlags []string, ignoreTests bool, patterns []string) ([]uncheckedError, error) {
	loadConfig := &packages.Config{
		Mode:       packages.NeedName | packages.NeedTypes | packages.NeedSyntax | packages.NeedTypesInfo,
		Tests:      !ignoreTests,
		BuildFlags: buildFlags,
	}
	pkgs, err := packages.Load(loadConfig, patterns...)
	if err != nil {
		return nil, err
	}
	for _, pkg := range pkgs {
		if len(pkg.Errors) != 0 {
			return nil, fmt.Errorf("errors while loading package %s: %v", pkg.PkgPath, pkg.Errors)
		}
	}

	var all []uncheckedError
	for _, pkg := range pkgs {
		if cfg.verbose {
			_, _ = fmt.Fprintf(os.Stderr, "checking %s\n", pkg.PkgPath)
		}
		visitor := &packageVisitor{
			pkg:      pkg,
			cfg:      cfg,
			checked: make(map[*ast.TypeAssertExpr]bool),
		}
		for _, file := range pkg.Syntax {
			if cfg.ignoreGenerated && isGenerated(file) {
				continue
			}
			visitor.checked = make(map[*ast.TypeAssertExpr]bool)
			visitor.currentFile = file
			ast.Inspect(file, visitor.visit)
		}
		all = append(all, visitor.errors...)
	}

	sortErrors(all)
	return deduplicateErrors(all), nil
}

func sortErrors(errors []uncheckedError) {
	sort.SliceStable(errors, func(i, j int) bool {
		a, b := errors[i].pos, errors[j].pos
		if a.Filename != b.Filename {
			return a.Filename < b.Filename
		}
		if a.Line != b.Line {
			return a.Line < b.Line
		}
		if a.Column != b.Column {
			return a.Column < b.Column
		}
		if errors[i].selector != errors[j].selector {
			return errors[i].selector < errors[j].selector
		}
		return errors[i].line < errors[j].line
	})
}

func deduplicateErrors(errors []uncheckedError) []uncheckedError {
	if len(errors) == 0 {
		return errors
	}
	out := errors[:1]
	for _, item := range errors[1:] {
		previous := out[len(out)-1]
		if previous.pos.Filename == item.pos.Filename &&
			previous.pos.Line == item.pos.Line &&
			previous.pos.Column == item.pos.Column &&
			previous.selector == item.selector &&
			previous.line == item.line {
			continue
		}
		out = append(out, item)
	}
	return out
}

var generatedPattern = regexp.MustCompile(`^// Code generated .* DO NOT EDIT\.$`)

func isGenerated(file *ast.File) bool {
	for _, group := range file.Comments {
		for _, comment := range group.List {
			if generatedPattern.MatchString(comment.Text) {
				return true
			}
		}
	}
	return false
}

func readLine(filename string, lineNumber int) string {
	if lineNumber <= 0 {
		return "??"
	}
	file, err := os.Open(filename)
	if err != nil {
		return "??"
	}
	defer func() { _ = file.Close() }()

	scanner := bufio.NewScanner(file)
	for current := 1; scanner.Scan(); current++ {
		if current == lineNumber {
			return strings.TrimSpace(scanner.Text())
		}
	}
	return "??"
}

type packageVisitor struct {
	pkg         *packages.Package
	cfg         checkerConfig
	errors      []uncheckedError
	checked     map[*ast.TypeAssertExpr]bool
	currentFile *ast.File
}

func (v *packageVisitor) add(pos token.Pos, selector string) {
	if v.pkg == nil || v.pkg.Fset == nil {
		return
	}
	position := v.pkg.Fset.Position(pos)
	v.errors = append(v.errors, uncheckedError{
		pos:      position,
		selector: selector,
		line:     readLine(position.Filename, position.Line),
	})
}

func (v *packageVisitor) visit(node ast.Node) bool {
	switch n := node.(type) {
	case *ast.ExprStmt:
		if call, ok := n.X.(*ast.CallExpr); ok {
			v.checkCall(call, call.Lparen)
		}
	case *ast.GoStmt:
		v.checkCall(n.Call, n.Call.Lparen)
	case *ast.DeferStmt:
		v.checkCall(n.Call, n.Call.Lparen)
	case *ast.AssignStmt:
		v.checkAssignment(n.Lhs, n.Rhs)
	case *ast.ValueSpec:
		lhs := make([]ast.Expr, len(n.Names))
		for i, name := range n.Names {
			lhs[i] = name
		}
		v.checkAssignment(lhs, n.Values)
	case *ast.TypeAssertExpr:
		if v.cfg.asserts && n.Type != nil && !v.checked[n] {
			v.add(n.Pos(), "")
		}
	}
	return true
}

func isBlank(expr ast.Expr) bool {
	ident, ok := expr.(*ast.Ident)
	return ok && ident.Name == "_"
}

func (v *packageVisitor) checkAssignment(lhs, rhs []ast.Expr) {
	if len(rhs) == 1 && len(lhs) == 2 {
		if assertion, ok := rhs[0].(*ast.TypeAssertExpr); ok && assertion.Type != nil {
			v.checked[assertion] = true
			if v.cfg.blank && v.cfg.asserts && isBlank(lhs[1]) {
				v.add(lhs[1].Pos(), "")
			}
		}
	}

	// A type assertion in an assignment that has more than one right-hand
	// side is necessarily the one-value form.  It is reported both at the
	// corresponding left-hand side and (when the node itself is visited)
	// at the assertion.
	if v.cfg.asserts && len(rhs) > 1 {
		for i, expr := range rhs {
			if _, ok := expr.(*ast.TypeAssertExpr); ok && i < len(lhs) {
				v.add(lhs[i].Pos(), "")
			}
		}
	}

	if !v.cfg.blank {
		return
	}

	if len(rhs) == 1 {
		call, ok := rhs[0].(*ast.CallExpr)
		if !ok {
			return
		}
		results := callResultTypes(v.pkg.TypesInfo, call)
		if len(results) == 0 {
			return
		}
		hasBlankError := false
		for i, expr := range lhs {
			if i < len(results) && isBlank(expr) && isErrorType(results[i]) {
				hasBlankError = true
				break
			}
		}
		if !hasBlankError || v.shouldSkip(call) {
			return
		}
		selector := selectorName(v.pkg.TypesInfo, call)
		for i, expr := range lhs {
			if i < len(results) && isBlank(expr) && isErrorType(results[i]) {
				v.add(expr.Pos(), selector)
			}
		}
		return
	}

	for i, expr := range rhs {
		if i >= len(lhs) || !isBlank(lhs[i]) {
			continue
		}
		call, ok := expr.(*ast.CallExpr)
		if !ok {
			continue
		}
		if !callReturnsError(v.pkg.TypesInfo, call) || v.shouldSkip(call) {
			continue
		}
		v.add(lhs[i].Pos(), selectorName(v.pkg.TypesInfo, call))
	}
}

func (v *packageVisitor) checkCall(call *ast.CallExpr, pos token.Pos) {
	if call == nil {
		return
	}
	if !callReturnsError(v.pkg.TypesInfo, call) {
		return
	}
	if v.shouldSkip(call) {
		return
	}
	v.add(pos, selectorName(v.pkg.TypesInfo, call))
}

func (v *packageVisitor) shouldSkip(call *ast.CallExpr) bool {
	return v.isIgnored(call) || v.isExcluded(call)
}

func callResultTypes(info *types.Info, call *ast.CallExpr) []types.Type {
	if info == nil || call == nil {
		return nil
	}
	t := info.TypeOf(call)
	if t == nil {
		return nil
	}
	if tuple, ok := t.(*types.Tuple); ok {
		results := make([]types.Type, tuple.Len())
		for i := range results {
			results[i] = tuple.At(i).Type()
		}
		return results
	}
	return []types.Type{t}
}

func callReturnsError(info *types.Info, call *ast.CallExpr) bool {
	for _, result := range callResultTypes(info, call) {
		if isErrorType(result) {
			return true
		}
	}
	return false
}

var errorInterface = types.Universe.Lookup("error").Type().Underlying().(*types.Interface)

func isErrorType(t types.Type) bool {
	if t == nil {
		return false
	}
	switch t.(type) {
	case *types.Named, *types.Pointer:
		return types.Implements(t, errorInterface)
	default:
		return false
	}
}

func objectOf(info *types.Info, ident *ast.Ident) types.Object {
	if info == nil || ident == nil {
		return nil
	}
	if obj := info.Uses[ident]; obj != nil {
		return obj
	}
	return info.Defs[ident]
}

func selectorFunc(info *types.Info, call *ast.CallExpr) (*ast.SelectorExpr, *types.Func) {
	if info == nil || call == nil {
		return nil, nil
	}
	selector, ok := call.Fun.(*ast.SelectorExpr)
	if !ok {
		return nil, nil
	}
	fn, ok := objectOf(info, selector.Sel).(*types.Func)
	if !ok {
		return selector, nil
	}
	return selector, fn
}

func selectorName(info *types.Info, call *ast.CallExpr) string {
	_, fn := selectorFunc(info, call)
	if fn == nil {
		return ""
	}
	return fn.FullName()
}

func (v *packageVisitor) isIgnored(call *ast.CallExpr) bool {
	if len(v.cfg.ignore) == 0 {
		return false
	}
	var name string
	var obj types.Object
	switch fun := call.Fun.(type) {
	case *ast.Ident:
		name = fun.Name
		obj = objectOf(v.pkg.TypesInfo, fun)
	case *ast.SelectorExpr:
		name = fun.Sel.Name
		obj = objectOf(v.pkg.TypesInfo, fun.Sel)
	default:
		return false
	}
	pkgPath := ""
	if obj != nil && obj.Pkg() != nil {
		pkgPath = obj.Pkg().Path()
	}
	for pkg, re := range v.cfg.ignore {
		if pkg != "" && pkg != pkgPath {
			continue
		}
		if re.MatchString(name) {
			return true
		}
	}
	return false
}

func pathQualifier(pkg *types.Package) string {
	if pkg == nil {
		return ""
	}
	return pkg.Path()
}

func (v *packageVisitor) isExcluded(call *ast.CallExpr) bool {
	if len(v.cfg.excludes) == 0 {
		return false
	}
	selector, fn := selectorFunc(v.pkg.TypesInfo, call)
	if fn == nil {
		return false
	}

	candidates := map[string]bool{fn.FullName(): true}

	if selector != nil && v.pkg.TypesInfo != nil {
		if selection := v.pkg.TypesInfo.Selections[selector]; selection != nil {
			for _, chainType := range selectionChain(selection) {
				addInterfaceCandidates(chainType, fn, candidates)
			}
		}
	}

	var argument string
	hasArgument := false
	if len(call.Args) != 0 {
		argument, hasArgument = argumentDescription(v.pkg.TypesInfo, call.Args[0])
	}

	for candidate := range candidates {
		if v.cfg.excludes[candidate] {
			return true
		}
		if hasArgument && v.cfg.excludes[candidate+"("+argument+")"] {
			return true
		}
	}
	return false
}

func argumentDescription(info *types.Info, arg ast.Expr) (string, bool) {
	if info == nil || arg == nil {
		return "", false
	}
	if selector, ok := arg.(*ast.SelectorExpr); ok {
		if selector.Sel.Name == "Stdout" || selector.Sel.Name == "Stderr" {
			if variable, ok := objectOf(info, selector.Sel).(*types.Var); ok {
				if variable.Pkg() != nil && variable.Pkg().Name() == "os" {
					return "os." + selector.Sel.Name, true
				}
			}
		}
	}
	t := info.TypeOf(arg)
	if t == nil {
		return "", false
	}
	return types.TypeString(t, pathQualifier), true
}

// selectionChain returns the type of the receiver expression and the types
// of any embedded fields traversed to reach a promoted method.  For an
// interface method, go/types records selections differently: the index is
// a single entry in the flattened method set.  In that case only the
// receiver type is returned and its embedded interfaces are examined by
// addInterfaceCandidates.
func selectionChain(selection *types.Selection) []types.Type {
	if selection == nil {
		return nil
	}
	chain := []types.Type{selection.Recv()}
	current := selection.Recv()
	index := selection.Index()
	if len(index) <= 1 {
		return chain
	}
	for _, fieldIndex := range index[:len(index)-1] {
		next := selectionFieldType(current, fieldIndex)
		if next == nil {
			break
		}
		chain = append(chain, next)
		current = next
	}
	return chain
}

func selectionFieldType(current types.Type, fieldIndex int) types.Type {
	t := current
	for {
		pointer, ok := t.(*types.Pointer)
		if !ok {
			break
		}
		t = pointer.Elem()
	}
	if t == nil {
		return nil
	}
	structure, ok := t.Underlying().(*types.Struct)
	if !ok || fieldIndex < 0 || fieldIndex >= structure.NumFields() {
		return nil
	}
	return structure.Field(fieldIndex).Type()
}

func addInterfaceCandidates(start types.Type, called *types.Func, candidates map[string]bool) {
	if start == nil || called == nil {
		return
	}
	visited := make(map[types.Type]bool)
	var visit func(types.Type)
	visit = func(current types.Type) {
		if current == nil || visited[current] {
			return
		}
		visited[current] = true

		iface, ok := current.Underlying().(*types.Interface)
		if !ok {
			return
		}
		if named, ok := current.(*types.Named); ok {
			if interfaceLeadsToMethod(named, called) {
				name := "(" + types.TypeString(named, pathQualifier) + ")." + called.Name()
				candidates[name] = true
			}
		}
		for i := 0; i < iface.NumEmbeddeds(); i++ {
			visit(iface.EmbeddedType(i))
		}
	}
	visit(start)
}

func interfaceLeadsToMethod(iface types.Type, called *types.Func) bool {
	selection := types.NewMethodSet(iface).Lookup(called.Pkg(), called.Name())
	if selection == nil {
		return false
	}
	fn, ok := selection.Obj().(*types.Func)
	if !ok {
		return false
	}
	return fn.Origin() == called.Origin()
}
GO
"}

